/**
 * @name Path traversal
 * @description Using untrusted input in file paths can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      // File open operations
      call = API::builtin("open").getACall() and
      sink = call.getArg(0)
    )
    or
    exists(API::CallNode call |
      // os.path operations that could be used with file access
      call = API::moduleImport("os").getMember(["open", "remove", "rename", "unlink", "mkdir", "rmdir"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "user input"

/**
 * @name Protobuf parsing with untrusted data
 * @description Parsing untrusted protobuf data could lead to denial of service or other issues
 * @kind path-problem
 * @problem.severity warning
 * @id py/protobuf-untrusted-parsing
 * @tags security
 *        external/cwe/cwe-20
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module ProtobufParsingConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for protobuf parsing methods like ParseFromString, Parse, MergeFromString
    exists(API::CallNode call |
      // Message parsing methods
      (call = API::moduleImport("google.protobuf.message").getMember(["ParseFromString", "Parse", "MergeFromString"]).getACall() and
       sink = call.getArg(0))
      or
      // Text format parsing
      (call = API::moduleImport("google.protobuf.text_format").getMember(["Parse", "Merge"]).getACall() and
       sink = call.getArg(0))
    )
  }
}

module ProtobufParsingFlow = TaintTracking::Global<ProtobufParsingConfig>;
import ProtobufParsingFlow::PathGraph

from ProtobufParsingFlow::PathNode source, ProtobufParsingFlow::PathNode sink
where ProtobufParsingFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Protobuf parsing with untrusted data from $@.", source.getNode(), "user input"

